import threading
from socket import timeout
from time import sleep
import paramiko

from ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions import DataTransferCreationException


class AppServerRunner(threading.Thread):
    """App Server Runner based on python thread"""

    def __init__(self, app_server_ip, app_server_username, app_server_password, app_server_lte_ip, logger):
        """

        :param app_server_ip:
        :param app_server_username:
        :param app_server_password:
        :param app_server_lte_ip:
        :param logger:
        """
        super(AppServerRunner, self).__init__()
        self.logger = logger
        self.app_server_ip = app_server_ip
        self.app_sever_username = app_server_username
        self.app_server_password = app_server_password
        self.app_server_lte_ip = app_server_lte_ip
        self.ssh_session = None
        self.analyzer = None
        self.pid = None
        self.breakpoint = threading.Event()
        self.log_path = None

    def _setup_ssh_connection(self):
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(self.app_server_ip, username=self.app_sever_username, password=self.app_server_password)
            self.logger.debug("SSH connection with App Server successfully established.")
            return ssh
        except Exception as e:
            raise DataTransferCreationException(
                "Unable to setup connection with AppServer, cause: {}".format(repr(e)))

    def _teardown_ssh_connection(self):
        self.ssh_session.close()
        self.logger.debug("SSH connection with App Server closed.")

    def _run_loop(self, command):
        try:
            self.ssh_session = self._setup_ssh_connection()
        except Exception:
            raise
        self.breakpoint.set()
        channel = self.ssh_session.invoke_shell()
        channel.settimeout(timeout=15)
        line_buffer = ''
        channel.recv(2048)  # Skip initial messages

        # FZMSVCP-53 adding PID handling for properly closing iperf on AppServer
        command = 'echo $$; exec ' + command
        self.logger.debug("Starting throughput loop. Command being executed: {}".format(command))
        channel.send("{}".format(command) + '\r')

        channel.settimeout(timeout=1)
        while self.breakpoint.is_set():
            try:
                channel_buffer = channel.recv(1).decode('UTF-8')
            except timeout:
                continue
            if len(channel_buffer) == 0:
                break
            channel_buffer = channel_buffer.replace('\r', '')
            line_buffer = self._process_buffer(channel_buffer, line_buffer)

        self.analyzer.append_current_statistics()
        self._kill_app_server_iperf()
        self._teardown_ssh_connection()

    def _process_buffer(self, channel_buffer, line_buffer):
        if channel_buffer != '\n':
            line_buffer += channel_buffer
        else:
            # FZMSVCP-53
            if not self.pid:
                try:
                    self.pid = int(line_buffer)
                    self.logger.debug("PID for app-server process is set to {}".format(self.pid))
                except Exception as e:
                    self.logger.info(str(e))
            self.analyzer.append_log_line(line_buffer)
            line_buffer = ''
        return line_buffer

    def _kill_app_server_iperf(self):
        if self.pid:
            chan = self.ssh_session.get_transport().open_session()
            chan.exec_command("kill -9 {}".format(self.pid))
            exit_status = chan.recv_exit_status()

            if exit_status != 0:
                self.logger.info("Unable to kill iPerf process on AppServer, exit status: {}".format(exit_status))
        else:
            self.logger.warning("PID for app-server process not found... Unable to kill iperf application.")

    def run(self):
        """
        :return: None
        :raises: :py:class:`ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions.DataTransferCreationException`: If this class has instance
        """
        raise DataTransferCreationException("AppServerRunner class cannot be instantiated as DataTransfer object.")

    def stop(self):
        """Stop the AppSvr thread."""
        self.breakpoint.clear()
        while self.is_running():
            sleep(0.5)

    def is_running(self):
        """
        Check if data AppSrv is running

        :return: boolean
        """
        # logger.debug("{} is_alive status: {}".format(self.__class__.__name__, self.isAlive()))
        return self.isAlive()

    def get_statistics(self):
        """
        Return dictionary with traffic stats

        :return: dict
        """
        return self.analyzer.get_results()

    def reset_statistics(self):
        """Clear stats."""
        self.analyzer.reset_statistics()
